from reports.export import export_csv

class TestExport(unittest.TestCase):
    def test_empty_rows(self):
        self.assertEqual(export_csv([], ['name']), 'name\n')

    def test_empty_columns(self):
        self.assertEqual(export_csv([{'name': 'Ada'}], []), '')

    def test_header_and_rows(self):
        self.assertEqual(export_csv([{'name': 'Ada', 'score': 3}], ['name', 'score']),
            'name,score\nAda,3\n')

    def test_quoting_and_missing(self):
        self.assertEqual(export_csv([{'name': 'A,"B"'}], ['name', 'score']),
            'name,score\n"A,""B""",\n')

